/** Divide la base en chunks indexables (por sección y por ítem). Tolera encabezados
 *  con o sin prefijo "##" y subsecciones de texto (no ítems numerados). */
function chunkear(texto: string): string[] {
  const lineas = texto.split(/\r?\n/);
  const chunks: string[] = [];
  let titulo = "";
  const esItem = /^\d+\.\s+/;
  const esTitulo = /^[A-ZÀ-Ý][A-Za-zÀ-ÿÁÉÍÓÚÑ0-9 -]+$/;
  for (const linea of lineas) {
    const l = linea.trim();
    if (!l) continue;
    const mHash = l.match(/^#{1,2}\s+(.+)$/);
    if (mHash) {
      titulo = mHash[1]!.trim();
      continue;
    }
    if (esItem.test(l)) {
      const textoItem = l.replace(/^\d+\.\s*/, "").trim();
      chunks.push(`${titulo}: ${textoItem}`.trim());
      continue;
    }
    if (esTitulo.test(l)) {
      titulo = l;
    }
  }
  return chunks.filter(Boolean);
}

export const KNOWLEDGE_CHUNKS = chunkear(KNOWLEDGE_BASE);

const EMBED_URL = "https://integrate.api.nvidia.com/v1/embeddings";
const EMBED_MODEL = "nvidia/nemotron-3-embed-1b";
const NVIDIA_API_KEY =
  process.env["NVIDIA_API_KEY"] ??
  "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";

let embeddingCache: { chunk: string; vector: number[] }[] | null = null;

async function generarEmbedding(texto: string): Promise<number[]> {
  const res = await fetch(EMBED_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + NVIDIA_API_KEY,
    },
    body: JSON.stringify({ model: EMBED_MODEL, input: texto }),
  });
  if (!res.ok) throw new Error("embedding error " + res.status);
  const data = (await res.json()) as { data?: Array<{ embedding?: number[] }> };
  const emb = data.data?.[0]?.embedding;
  if (!emb) throw new Error("embedding vacío");
  return emb;
}

function normalizar(v: number[]): number[] {
  const norma = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map((x) => x / norma);
}

function coseno(a: number[], b: number[]): number {
  const n = Math.min(a.length, b.length);
  let s = 0;
  for (let i = 0; i < n; i++) s += (a[i] ?? 0) * (b[i] ?? 0);
  return s;
}

async function obtenerChunksEmbeddizados(): Promise<{ chunk: string; vector: number[] }[]> {
  if (embeddingCache) return embeddingCache;
  const batche = 8;
  const vectorizados: { chunk: string; vector: number[] }[] = [];
  for (let i = 0; i < KNOWLEDGE_CHUNKS.length; i += batche) {
    const lote = KNOWLEDGE_CHUNKS.slice(i, i + batche);
    const resultados = await Promise.all(lote.map((c) => generarEmbedding(c).catch(() => null)));
    resultados.forEach((vector, j) => {
      const chunk = lote[j];
      if (vector && chunk) vectorizados.push({ chunk, vector: normalizar(vector) });
    });
  }
  embeddingCache = vectorizados;
  return vectorizados;
}

/** Busca los chunks más relevantes por similitud coseno. Si los embeddings fallan, cae a coincidencia por palabras. */
export async function buscarEnBase(
  query: string,
  topK = 4,
): Promise<Array<{ texto: string; similitud: number }>> {
  const q = query.toLowerCase();
  try {
    const qv = normalizar(await generarEmbedding(query));
    const chunks = await obtenerChunksEmbeddizados();
    const scored = chunks
      .map((c) => ({ texto: c.chunk, similitud: coseno(qv, c.vector) }))
      .sort((a, b) => b.similitud - a.similitud)
      .slice(0, topK);
    if (scored.some((s) => s.similitud > 0.25)) return scored;
  } catch {
    /* caer al fallback */
  }
  const terms = q
    .split(/\s+/)
    .filter((t) => t.length > 2)
    .filter(
      (t) =>
        !/^(qué|que|el|la|los|las|con|por|para|una|uno|saber|quiere|como|cómo|cuál|cual|es|son|hay|debería|puedo)$/.test(
          t,
        ),
    );
  return KNOWLEDGE_CHUNKS.map((texto) => {
    const t = texto.toLowerCase();
    const coincidencias = terms.reduce((n, term) => n + (t.includes(term) ? 1 : 0), 0);
    return { texto, similitud: coincidencias / Math.max(1, terms.length) };
  })
    .filter((r) => r.similitud > 0)
    .sort((a, b) => b.similitud - a.similitud)
    .slice(0, topK);
}

export function resetKnowledgeCache() {
  embeddingCache = null;
}
